func OwnerConfigContainsFold(v string) predicate.RuntimeState {
	return predicate.RuntimeState(sql.FieldContainsFold(FieldOwnerConfig, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RuntimeState) predicate.RuntimeState {
	return predicate.RuntimeState(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RuntimeState) predicate.RuntimeState {
	return predicate.RuntimeState(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RuntimeState) predicate.RuntimeState {
	return predicate.RuntimeState(sql.NotPredicates(p))
}
